import json

commands = []

def set_cell(pattern, row, channel, note_name=None, inst=None, vol=None, effect=None, param=None):
    notes = {'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 
             'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11}

    cell = {"pattern": pattern, "row": row, "channel": channel}

    if note_name:
        if note_name == "===":
            cell["note"] = 97
        else:
            if len(note_name) == 3:
                if note_name[1] == '-':
                    n = notes[note_name[0]]
                    octave = int(note_name[2])
                elif note_name[1] == '#':
                    n = notes[note_name[0:2]]
                    octave = int(note_name[2])
            n_val = 1 + octave * 12 + n
            cell["note"] = n_val

    if inst:
        cell["instrument"] = inst
    if vol is not None:
        cell["volume"] = vol
    if effect is not None:
        cell["effect"] = effect
    if param is not None:
        cell["effect_param"] = param

    commands.append({"name": "pattern_set_cell", "arguments": cell})

PLUCK = 8

# Add pluck fill notes in pattern 1 and 3 for more interest
# Pattern 1 - add some pluck echoes of the melody
pluck_pattern1 = [
    (2, "E-4", 40), (10, "D-4", 36), (18, "A-4", 40),
    (26, "D-4", 36), (34, "C-4", 40), (42, "E-4", 36),
    (50, "D-4", 40), (58, "A-4", 36)
]
for row, note, vol in pluck_pattern1:
    set_cell(1, row, 6, note, PLUCK, vol)

# Pattern 3 - different pluck pattern
pluck_pattern3 = [
    (2, "C-4", 40), (10, "F-4", 36), (18, "G-4", 40),
    (26, "E-4", 36), (34, "B-3", 40), (42, "D-4", 36),
    (50, "C-4", 40), (58, "G#3", 36)
]
for row, note, vol in pluck_pattern3:
    set_cell(3, row, 6, note, PLUCK, vol)

# Add more dynamic variation with volume slides on some notes
# Pattern 2 - crescendo on pluck
for row in [0, 8, 16, 24]:
    set_cell(2, row + 4, 6, None, None, None, 0xA, 0x10)  # Volume slide up

# Pattern 4 - add some staccato cuts
for row in [7, 15, 23, 31, 39, 47, 55, 63]:
    set_cell(4, row, 0, "===", None, None)  # Cut lead for staccato feel

with open('/workspace/enhance_commands.json', 'w') as f:
    json.dump(commands, f)

print(f"Generated {len(commands)} enhancement commands")
EOF
